  (MvPolynomial.eval y) (QuaternaryQuadraticForms.coordinatePolynomial E i) = E y i

∀ {K : Type u_1} [inst : Field K] {ι : Type u_2}
  {κ : Type u_3} [inst_1 : Fintype ι] [inst_2 : DecidableEq ι] (E : (ι → K) →ₗ[K] κ → K) (i : κ),
  (QuaternaryQuadraticForms.coordinatePolynomial E i).IsHomogeneous 1

∀ {K : Type u_1} [inst : Field K] {N : ℕ}
